// Einmaliger Nachtrag 2026-08-01 (Nutzerfrage "haengt eine Bilderstellung/Prompterstellung
// irgendwo?"): 2026/189 (vol_10718) und 2026/190 (vol_10719) hatten headlineChoiceStage=
// 'headline_selected', aber imageHeadline/imageSubline blieben leer (visualJson='{}') - die
// urspruenglich per Matrix gewaehlten Kandidatentexte sind nicht mehr rekonstruierbar (keine
// passende alte Execution mehr verfuegbar, gleiche Situation wie beim dol_-Fall). P5s Weiche
// "IF Headline bereits gewaehlt?" prueft imageHeadline/imageSubline direkt (nicht das Stage-
// Feld) und liess beide Zeilen seit dem 31.07. jede Stunde lautlos durchfallen, ohne
// Fehlermeldung. Nutzerentscheidung: neu ueber Matrix waehlen lassen - Reset auf
// 'needs_kernbotschaft' (derselbe Zielzustand wie beim regulaeren Reroll-Pfad in P5b
// "Finde Sat-Antwort"), damit P3e beim naechsten Lauf frische Kandidaten baut und erneut in
// Matrix zur Auswahl postet.
const TARGETS = [
  { vorgangKey: 'vol_10719', vorgangsnummer: '2026/190' },
  { vorgangKey: 'vol_10718', vorgangsnummer: '2026/189' }
];

return TARGETS.map(t => ({
  json: {
    vorgangKey: t.vorgangKey,
    vorgangsnummer: t.vorgangsnummer,
    headlineChoiceStage: 'needs_kernbotschaft',
    imageHeadline: '',
    imageSubline: '',
    visualPromptStage: '',
    imageStage: 'not_started',
    visualJson: '{}'
  }
}));
